				$($($(".grid .row.tr")[j]).find(".col")[i]).find("i").text(gridText);
			}
		};
		/* SITE */
		$('.site').click(function(){
			if ($(this).hasClass('on')) {
				$(this).removeClass('on');
			} else {
				$(this).addClass('on');
